"""Bestiary art (your painted library sheet): background with the open book, picture frames, ink dividers, stars, page-turn tabs.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# spots in best_bg.jpg, in its own pixels
LIGHTS = ((535, 45, 44), (1333, 45, 44), (180, 572, 46), (1645, 492, 30), (45, 245, 30))   # candles and the lantern (x, y, radius)
PAGE_L = (372, 156, 905, 664)        # inside of the left page (left, top, right, bottom)
PAGE_R = (962, 152, 1500, 664)       # inside of the right page
CORNER_L = (305, 594, 386, 672)      # gold corner at the bottom left of the book (the back tab goes here)
CORNER_R = (1480, 594, 1562, 672)    # gold corner at the bottom right (the forward tab)
FRAME_EDGE = {'frame_ruins': 12, 'frame_forest': 12, 'frame_boss': 70}   # frame border width in the stored pieces
PNG = {
  'best_bg': ('jpg', ''),
  'frame_boss': ('png', ''),
  'frame_forest': ('png', ''),
  'frame_ruins': ('png', ''),
  'ink_divider': ('png', ''),
  'ink_flourish': ('png', ''),
  'star_off': ('png', ''),
  'star_on': ('png', ''),
  'tab_left': ('png', ''),
  'tab_right': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
